import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — edge cases", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
  });

  describe("quote — base premiums of main items (newcomer, first contract)", () => {
    it.todo("plain sword → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet → 60 base + 6 first insurance + 5 fee = 71 G");
    it.todo("plain staff → 80 base + 8 first insurance + 5 fee = 93 G");
    it.todo("plain potion → 40 base + 4 first insurance + 5 fee = 49 G");
  });

  describe("quote — components and building blocks", () => {
    it.todo("2 runes → 50 G base premium → 50 + 5 first insurance + 5 fee = 60 G");
    it.todo("3 runes → 60 G base premium (block) → 60 + 6 + 5 = 71 G");
    it.todo("4 runes → 100 G base premium (no block, block requires exactly 3) → 100 + 10 + 5 = 115 G");
    it.todo("7 runes → 175 G base premium → 175 + 17.5 + 5 = 197.5 → 198 G (rounded up)");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types) → 75 + 7.5 + 5 = 87.5 → 88 G");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks) → 120 + 12 + 5 = 137 G");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("newcomer with cursed steel sword, enchantment 3 → 100 + 50 curse + 10 first = 160 + 5 fee = 165 G");
    it.todo("sword with enchantment 4, not cursed → no high-enchantment surcharge → 115 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → 100 + 30 + 10 + 5 = 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges apply → 100 + 50 + 30 + 10 + 5 = 195 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge → 165 G");
    it.todo("cursed sword + plain amulet → curse applies only to sword: 160 base + 50 curse + 16 first + 5 fee = 231 G");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount applies: sword 100 − 20 + 10 + 5 = 95 G");
    it.todo("customer with 1 year → no loyalty discount: sword 115 G");
    it.todo("second quote in a scenario gets 15 % follow-up discount: sword 100 + 10 − 15 + 5 = 100 G");
    it.todo("long-standing customer's second contract: cursed sword enchantment 7, 3 years → 160 G (first insurance surcharge still applies)");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular steel sword enchantment 3, damage 500 → payout 400 G, remaining cap 1600 G");
    it.todo("rune (no enchantment/material), damage 200 → payout 100 G");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700 G");
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 G");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 → payout 400 G");
    it.todo("payout yielding 350.5 G → rounded down to 350 G (e.g. enchantment 9, damage 901)");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible per damaged item)");
    it.todo("two swords insured → cap 4000 G; damages to both swords each have own deductible");
  });

  describe("claim — cap", () => {
    it.todo("sword + amulet → insurance sum 1600, cap 3200: remaining cap after 500 damage to sword is 2800");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes (block) → insurance sum 1750 G, cap 3500 G");
    it.todo("two successive claims of 1500 G on a sword → payouts 1400 (remaining 600) then 600 (remaining 0)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → throws");
    it.todo("claim with damage to item not in policy (amulet when only sword insured) → throws");
    it.todo("claim with damage to item of unknown type → throws");
    it.todo("claim with more damage entries of a type than insured (two swords damaged, one insured) → throws");
    it.todo("claim with negative damage amount (-200) → throws");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout (schema example)");
    it.todo("exits non-zero and writes error to stderr, nothing to stdout, for unknown item type");
  });
});

