type Item = { type: string };
type Scenario = { steps: { items: Item[] }[] };
type ScenarioOutcome = { results: { premium: number }[] };

export const processScenario = (scenario: Scenario): ScenarioOutcome => {
  const items = scenario.steps[0].items;
  const basePremium = items.length > 0 ? 100 : 0;
  return { results: [{ premium: basePremium * 1.1 + 5 }] };
};
EOF
