type Item = { type?: string };
type QuoteStep = { op: "quote"; items: Item[] };
type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
type ScenarioOutcome = { results: { premium: number }[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const PROCESSING_FEE = 5;

const RUNE_BLOCK_SIZE = 3;
const RUNE_BLOCK_DISCOUNT = 15;

const runeBlockDiscount = (items: Item[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  return runeCount === RUNE_BLOCK_SIZE ? RUNE_BLOCK_DISCOUNT : 0;
};

const sumItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type ?? ""], 0);

const calculateBasePremium = (items: Item[]): number =>
  sumItemPremiums(items) - runeBlockDiscount(items);

const firstInsuranceSurcharge = (basePremium: number): number => basePremium / 10;

const quotePremium = (items: Item[]): number => {
  const basePremium = calculateBasePremium(items);
  return Math.ceil(basePremium + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE);
};

export const processScenario = (scenario: Scenario): ScenarioOutcome => {
  const { items } = scenario.steps[0];
  return { results: [{ premium: quotePremium(items) }] };
};

