const blockDiscount = (items: Item[]): number =>
  COMPONENT_TYPES.filter((componentType) => countOfType(items, componentType) === BLOCK_SIZE)
    .length * BLOCK_DISCOUNT;

const sumItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const calculateBasePremium = (items: Item[]): number =>
  sumItemPremiums(items) - blockDiscount(items);

const firstInsuranceSurcharge = (basePremium: number): number => basePremium / 10;

const curseSurcharge = (items: Item[]): number =>
  items
    .filter((item) => item.cursed)
    .reduce((sum, item) => sum + itemBasePremium(item) / 2, 0);

const quotePremium = (items: Item[]): number => {
  const basePremium = calculateBasePremium(items);
  return Math.ceil(
    basePremium + curseSurcharge(items) + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE,
  );
};

export const processScenario = (scenario: Scenario): ScenarioOutcome => {
  const { items } = scenario.steps[0];
  return { results: [{ premium: quotePremium(items) }] };
};

