content.content:
const DEDUCTIBLE = 100;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  rune: 250,
};

const COVERAGE_CAP_MULTIPLIER = 2;

const itemInsuranceValue = (item: Item): number => INSURANCE_VALUES[item.type ?? ""];

const coverageCap = (items: Item[]): number =>
  COVERAGE_CAP_MULTIPLIER * sumOf(items, itemInsuranceValue);

const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;

const reimbursableAmount = (damage: Damage, item: Item | undefined): number =>
  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
    ? percentOf(damage.amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
    : damage.amount;

const damagePayout = (damage: Damage, policyItems: Item[]): number => {
  const item = policyItems.find((policyItem) => policyItem.type === damage.itemType);
  return reimbursableAmount(damage, item) - DEDUCTIBLE;
};

const claimPayout = (claim: ClaimStep, policyItems: Item[]): number =>
  Math.floor(sumOf(claim.incident.damages, (damage) => damagePayout(damage, policyItems)));

const settleClaim = (claim: ClaimStep, policyItems: Item[]): ClaimResult => {
  const payout = claimPayout(claim, policyItems);
  return { payout, remainingCap: coverageCap(policyItems) - payout };
};

const insuredItemsOf = (steps: Step[], policy: number): Item[] =>
  (steps[policy] as QuoteStep).items;

export const processScenario = (scenario: Scenario): ScenarioOutcome => {
  const results = scenario.steps.map((step, previousContracts) =>
    step.op === "claim"
      ? settleClaim(step, insuredItemsOf(scenario.steps, step.policy))
      : { premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, previousContracts) },
  );
  return { results };
};

